17	package com.google.zxing.common.detector;
18	
19	import com.google.zxing.NotFoundException;
20	import com.google.zxing.ResultPoint;
21	import com.google.zxing.common.BitMatrix;
22	
23	/**
24	 * <p>
25	 * Detects a candidate barcode-like rectangular region within an image. It
26	 * starts around the center of the image, increases the size of the candidate
27	 * region until it finds a white rectangular region. By keeping track of the
28	 * last black points it encountered, it determines the corners of the barcode.
29	 * </p>
30	 *
31	 * @author David Olivier
32	 */
33	public final class WhiteRectangleDetector {
34	
35	  private static final int INIT_SIZE = 10;
36	  private static final int CORR = 1;
37	
38	  private final BitMatrix image;
39	  private final int height;
40	  private final int width;
41	  private final int leftInit;
42	  private final int rightInit;
43	  private final int downInit;
44	  private final int upInit;
45	
46	  public WhiteRectangleDetector(BitMatrix image) throws NotFoundException {
47	    this(image, INIT_SIZE, image.getWidth() / 2, image.getHeight() / 2);
48	  }
49	
50	  /**
51	   * @param image barcode image to find a rectangle in
52	   * @param initSize initial size of search area around center
53	   * @param x x position of search center
54	   * @param y y position of search center
55	   * @throws NotFoundException if image is too small to accommodate {@code initSize}
56	   */
57	  public WhiteRectangleDetector(BitMatrix image, int initSize, int x, int y) throws NotFoundException {
58	    this.image = image;
59	    height = image.getHeight();
60	    width = image.getWidth();
61	    int halfsize = initSize / 2;
62	    leftInit = x - halfsize;
63	    rightInit = x + halfsize;
64	    upInit = y - halfsize;
65	    downInit = y + halfsize;
66	    if (upInit < 0 || leftInit < 0 || downInit >= height || rightInit >= width) {
67	      throw NotFoundException.getNotFoundInstance();
68	    }
69	  }
70	
71	  /**
72	   * <p>
73	   * Detects a candidate barcode-like rectangular region within an image. It
74	   * starts around the center of the image, increases the size of the candidate
75	   * region until it finds a white rectangular region.
76	   * </p>
77	   *
78	   * @return {@link ResultPoint}[] describing the corners of the rectangular
79	   *         region. The first and last points are opposed on the diagonal, as
80	   *         are the second and third. The first point will be the topmost
81	   *         point and the last, the bottommost. The second point will be
82	   *         leftmost and the third, the rightmost
83	   * @throws NotFoundException if no Data Matrix Code can be found
84	   */
85	  public ResultPoint[] detect() throws NotFoundException {
86	
87	    int left = leftInit;
88	    int right = rightInit;
89	    int up = upInit;
90	    int down = downInit;
91	    boolean sizeExceeded = false;
92	    boolean aBlackPointFoundOnBorder = true;
93	
94	    boolean atLeastOneBlackPointFoundOnRight = false;
95	    boolean atLeastOneBlackPointFoundOnBottom = false;
96	    boolean atLeastOneBlackPointFoundOnLeft = false;
97	    boolean atLeastOneBlackPointFoundOnTop = false;
98	
99	    while (aBlackPointFoundOnBorder) {
100	
101	      aBlackPointFoundOnBorder = false;
102	
103	      // .....
104	      // .   |
105	      // .....
106	      boolean rightBorderNotWhite = true;
107	      while ((rightBorderNotWhite || !atLeastOneBlackPointFoundOnRight) && right < width) {
108	        rightBorderNotWhite = containsBlackPoint(up, down, right, false);
109	        if (rightBorderNotWhite) {
110	          right++;
111	          aBlackPointFoundOnBorder = true;
112	          atLeastOneBlackPointFoundOnRight = true;
113	        } else if (!atLeastOneBlackPointFoundOnRight) {
114	          right++;
115	        }
116	      }
117	
118	      if (right >= width) {
119	        sizeExceeded = true;
120	        break;
121	      }
122	
123	      // .....
124	      // .   .
125	      // .___.
126	      boolean bottomBorderNotWhite = true;
127	      while ((bottomBorderNotWhite || !atLeastOneBlackPointFoundOnBottom) && down < height) {
128	        bottomBorderNotWhite = containsBlackPoint(left, right, down, true);
129	        if (bottomBorderNotWhite) {
130	          down++;
131	          aBlackPointFoundOnBorder = true;
132	          atLeastOneBlackPointFoundOnBottom = true;
133	        } else if (!atLeastOneBlackPointFoundOnBottom) {
134	          down++;
135	        }
136	      }
137	
138	      if (down >= height) {
139	        sizeExceeded = true;
140	        break;
141	      }
142	
143	      // .....
144	      // |   .
145	      // .....
146	      boolean leftBorderNotWhite = true;
147	      while ((leftBorderNotWhite || !atLeastOneBlackPointFoundOnLeft) && left >= 0) {
148	        leftBorderNotWhite = containsBlackPoint(up, down, left, false);
149	        if (leftBorderNotWhite) {
150	          left--;
151	          aBlackPointFoundOnBorder = true;
152	          atLeastOneBlackPointFoundOnLeft = true;
153	        } else if (!atLeastOneBlackPointFoundOnLeft) {
154	          left--;
155	        }
156	      }
157	
158	      if (left < 0) {
159	        sizeExceeded = true;
160	        break;
161	      }
162	
163	      // .___.
164	      // .   .
165	      // .....
166	      boolean topBorderNotWhite = true;
167	      while ((topBorderNotWhite || !atLeastOneBlackPointFoundOnTop) && up >= 0) {
168	        topBorderNotWhite = containsBlackPoint(left, right, up, true);
169	        if (topBorderNotWhite) {
170	          up--;
171	          aBlackPointFoundOnBorder = true;
172	          atLeastOneBlackPointFoundOnTop = true;
173	        } else if (!atLeastOneBlackPointFoundOnTop) {
174	          up--;
175	        }
176	      }
177	
178	      if (up < 0) {
179	        sizeExceeded = true;
180	        break;
181	      }
182	
183	    }
184	
185	    if (!sizeExceeded) {
186	
187	      int maxSize = right - left;
188	
189	      ResultPoint z = null;
190	      for (int i = 1; z == null && i < maxSize; i++) {
191	        z = getBlackPointOnSegment(left, down - i, left + i, down);
192	      }
193	
194	      if (z == null) {
195	        throw NotFoundException.getNotFoundInstance();
196	      }
197	
198	      ResultPoint t = null;
199	      //go down right
200	      for (int i = 1; t == null && i < maxSize; i++) {
201	        t = getBlackPointOnSegment(left, up + i, left + i, up);
202	      }
203	
204	      if (t == null) {
205	        throw NotFoundException.getNotFoundInstance();
206	      }
207	
208	      ResultPoint x = null;
209	      //go down left
210	      for (int i = 1; x == null && i < maxSize; i++) {
211	        x = getBlackPointOnSegment(right, up + i, right - i, up);
212	      }
213	
214	      if (x == null) {
215	        throw NotFoundException.getNotFoundInstance();
216	      }
217	
218	      ResultPoint y = null;
219	      //go up left
220	      for (int i = 1; y == null && i < maxSize; i++) {
221	        y = getBlackPointOnSegment(right, down - i, right - i, down);
222	      }
223	
224	      if (y == null) {
225	        throw NotFoundException.getNotFoundInstance();
226	      }
227	
228	      return centerEdges(y, z, x, t);
229	
230	    } else {
231	      throw NotFoundException.getNotFoundInstance();
232	    }
233	  }
234	
235	  private ResultPoint getBlackPointOnSegment(float aX, float aY, float bX, float bY) {
236	    int dist = MathUtils.round(MathUtils.distance(aX, aY, bX, bY));
237	    float xStep = (bX - aX) / dist;
238	    float yStep = (bY - aY) / dist;
239	
240	    for (int i = 0; i < dist; i++) {
241	      int x = MathUtils.round(aX + i * xStep);
242	      int y = MathUtils.round(aY + i * yStep);
243	      if (image.get(x, y)) {
244	        return new ResultPoint(x, y);
245	      }
246	    }
247	    return null;
248	  }
249	
250	  /**
251	   * recenters the points of a constant distance towards the center
252	   *
253	   * @param y bottom most point
254	   * @param z left most point
255	   * @param x right most point
256	   * @param t top most point
257	   * @return {@link ResultPoint}[] describing the corners of the rectangular
258	   *         region. The first and last points are opposed on the diagonal, as
259	   *         are the second and third. The first point will be the topmost
260	   *         point and the last, the bottommost. The second point will be
261	   *         leftmost and the third, the rightmost
262	   */
263	  private ResultPoint[] centerEdges(ResultPoint y, ResultPoint z,
264	                                    ResultPoint x, ResultPoint t) {
265	
266	    //
267	    //       t            t
268	    //  z                      x
269	    //        x    OR    z
270	    //   y                    y
271	    //
272	
273	    float yi = y.getX();
274	    float yj = y.getY();
275	    float zi = z.getX();
276	    float zj = z.getY();
277	    float xi = x.getX();
278	    float xj = x.getY();
279	    float ti = t.getX();
280	    float tj = t.getY();
281	
282	    if (yi < width / 2.0f) {
283	      return new ResultPoint[]{
284	          new ResultPoint(ti - CORR, tj + CORR),
285	          new ResultPoint(zi + CORR, zj + CORR),
286	          new ResultPoint(xi - CORR, xj - CORR),
287	          new ResultPoint(yi + CORR, yj - CORR)};
288	    } else {
289	      return new ResultPoint[]{
290	          new ResultPoint(ti + CORR, tj + CORR),
291	          new ResultPoint(zi + CORR, zj - CORR),
292	          new ResultPoint(xi - CORR, xj + CORR),
293	          new ResultPoint(yi - CORR, yj - CORR)};
294	    }
295	  }
296	
297	  /**
298	   * Determines whether a segment contains a black point
299	   *
300	   * @param a          min value of the scanned coordinate
301	   * @param b          max value of the scanned coordinate
302	   * @param fixed      value of fixed coordinate
303	   * @param horizontal set to true if scan must be horizontal, false if vertical
304	   * @return true if a black point has been found, else false.
305	   */
306	  private boolean containsBlackPoint(int a, int b, int fixed, boolean horizontal) {
307	
308	    if (horizontal) {
309	      for (int x = a; x <= b; x++) {
310	        if (image.get(x, fixed)) {
311	          return true;
312	        }
313	      }
314	    } else {
315	      for (int y = a; y <= b; y++) {
316	        if (image.get(fixed, y)) {
317	          return true;
318	        }
319	      }
320	    }
321	
322	    return false;
323	  }
324	
325	}
