18	
19	import com.google.zxing.NotFoundException;
20	import com.google.zxing.ResultPoint;
21	import com.google.zxing.common.BitMatrix;
22	
23	/**
24	 * <p>A somewhat generic detector that looks for a barcode-like rectangular region within an image.
25	 * It looks within a mostly white region of an image for a region of black and white, but mostly
26	 * black. It returns the four corners of the region, as best it can determine.</p>
27	 *
28	 * @author Sean Owen
29	 * @deprecated without replacement since 3.3.0
30	 */
31	@Deprecated
32	public final class MonochromeRectangleDetector {
33	
34	  private static final int MAX_MODULES = 32;
35	
36	  private final BitMatrix image;
37	
38	  public MonochromeRectangleDetector(BitMatrix image) {
39	    this.image = image;
40	  }
41	
42	  /**
43	   * <p>Detects a rectangular region of black and white -- mostly black -- with a region of mostly
44	   * white, in an image.</p>
45	   *
46	   * @return {@link ResultPoint}[] describing the corners of the rectangular region. The first and
47	   *  last points are opposed on the diagonal, as are the second and third. The first point will be
48	   *  the topmost point and the last, the bottommost. The second point will be leftmost and the
49	   *  third, the rightmost
50	   * @throws NotFoundException if no Data Matrix Code can be found
51	   */
52	  public ResultPoint[] detect() throws NotFoundException {
53	    int height = image.getHeight();
54	    int width = image.getWidth();
55	    int halfHeight = height / 2;
56	    int halfWidth = width / 2;
57	    int deltaY = Math.max(1, height / (MAX_MODULES * 8));
58	    int deltaX = Math.max(1, width / (MAX_MODULES * 8));
59	
60	    int top = 0;
61	    int bottom = height;
62	    int left = 0;
63	    int right = width;
64	    ResultPoint pointA = findCornerFromCenter(halfWidth, 0, left, right,
65	        halfHeight, -deltaY, top, bottom, halfWidth / 2);
66	    top = (int) pointA.getY() - 1;
67	    ResultPoint pointB = findCornerFromCenter(halfWidth, -deltaX, left, right,
68	        halfHeight, 0, top, bottom, halfHeight / 2);
69	    left = (int) pointB.getX() - 1;
70	    ResultPoint pointC = findCornerFromCenter(halfWidth, deltaX, left, right,
71	        halfHeight, 0, top, bottom, halfHeight / 2);
72	    right = (int) pointC.getX() + 1;
73	    ResultPoint pointD = findCornerFromCenter(halfWidth, 0, left, right,
74	        halfHeight, deltaY, top, bottom, halfWidth / 2);
75	    bottom = (int) pointD.getY() + 1;
76	
77	    // Go try to find point A again with better information -- might have been off at first.
78	    pointA = findCornerFromCenter(halfWidth, 0, left, right,
79	        halfHeight, -deltaY, top, bottom, halfWidth / 4);
80	
81	    return new ResultPoint[] { pointA, pointB, pointC, pointD };
82	  }
83	
84	  /**
85	   * Attempts to locate a corner of the barcode by scanning up, down, left or right from a center
86	   * point which should be within the barcode.
87	   *
88	   * @param centerX center's x component (horizontal)
89	   * @param deltaX same as deltaY but change in x per step instead
90	   * @param left minimum value of x
91	   * @param right maximum value of x
92	   * @param centerY center's y component (vertical)
93	   * @param deltaY change in y per step. If scanning up this is negative; down, positive;
94	   *  left or right, 0
95	   * @param top minimum value of y to search through (meaningless when di == 0)
96	   * @param bottom maximum value of y
97	   * @param maxWhiteRun maximum run of white pixels that can still be considered to be within
98	   *  the barcode
99	   * @return a {@link ResultPoint} encapsulating the corner that was found
100	   * @throws NotFoundException if such a point cannot be found
101	   */
102	  private ResultPoint findCornerFromCenter(int centerX,
103	                                           int deltaX,
104	                                           int left,
105	                                           int right,
106	                                           int centerY,
107	                                           int deltaY,
108	                                           int top,
109	                                           int bottom,
110	                                           int maxWhiteRun) throws NotFoundException {
111	    int[] lastRange = null;
112	    for (int y = centerY, x = centerX;
113	         y < bottom && y >= top && x < right && x >= left;
114	         y += deltaY, x += deltaX) {
115	      int[] range;
116	      if (deltaX == 0) {
117	        // horizontal slices, up and down
118	        range = blackWhiteRange(y, maxWhiteRun, left, right, true);
119	      } else {
120	        // vertical slices, left and right
121	        range = blackWhiteRange(x, maxWhiteRun, top, bottom, false);
122	      }
123	      if (range == null) {
124	        if (lastRange == null) {
125	          throw NotFoundException.getNotFoundInstance();
126	        }
127	        // lastRange was found
128	        if (deltaX == 0) {
129	          int lastY = y - deltaY;
130	          if (lastRange[0] < centerX) {
131	            if (lastRange[1] > centerX) {
132	              // straddle, choose one or the other based on direction
133	              return new ResultPoint(lastRange[deltaY > 0 ? 0 : 1], lastY);
134	            }
135	            return new ResultPoint(lastRange[0], lastY);
136	          } else {
137	            return new ResultPoint(lastRange[1], lastY);
138	          }
139	        } else {
140	          int lastX = x - deltaX;
141	          if (lastRange[0] < centerY) {
142	            if (lastRange[1] > centerY) {
143	              return new ResultPoint(lastX, lastRange[deltaX < 0 ? 0 : 1]);
144	            }
145	            return new ResultPoint(lastX, lastRange[0]);
146	          } else {
147	            return new ResultPoint(lastX, lastRange[1]);
148	          }
149	        }
150	      }
151	      lastRange = range;
152	    }
153	    throw NotFoundException.getNotFoundInstance();
154	  }
155	
156	  /**
157	   * Computes the start and end of a region of pixels, either horizontally or vertically, that could
158	   * be part of a Data Matrix barcode.
159	   *
160	   * @param fixedDimension if scanning horizontally, this is the row (the fixed vertical location)
161	   *  where we are scanning. If scanning vertically it's the column, the fixed horizontal location
162	   * @param maxWhiteRun largest run of white pixels that can still be considered part of the
163	   *  barcode region
164	   * @param minDim minimum pixel location, horizontally or vertically, to consider
165	   * @param maxDim maximum pixel location, horizontally or vertically, to consider
166	   * @param horizontal if true, we're scanning left-right, instead of up-down
167	   * @return int[] with start and end of found range, or null if no such range is found
168	   *  (e.g. only white was found)
169	   */
170	  private int[] blackWhiteRange(int fixedDimension, int maxWhiteRun, int minDim, int maxDim, boolean horizontal) {
171	
172	    int center = (minDim + maxDim) / 2;
173	
174	    // Scan left/up first
175	    int start = center;
176	    while (start >= minDim) {
177	      if (horizontal ? image.get(start, fixedDimension) : image.get(fixedDimension, start)) {
178	        start--;
179	      } else {
180	        int whiteRunStart = start;
181	        do {
182	          start--;
183	        } while (start >= minDim && !(horizontal ? image.get(start, fixedDimension) :
184	            image.get(fixedDimension, start)));
185	        int whiteRunSize = whiteRunStart - start;
186	        if (start < minDim || whiteRunSize > maxWhiteRun) {
187	          start = whiteRunStart;
188	          break;
189	        }
190	      }
191	    }
192	    start++;
193	
194	    // Then try right/down
195	    int end = center;
196	    while (end < maxDim) {
197	      if (horizontal ? image.get(end, fixedDimension) : image.get(fixedDimension, end)) {
198	        end++;
199	      } else {
200	        int whiteRunStart = end;
201	        do {
202	          end++;
203	        } while (end < maxDim && !(horizontal ? image.get(end, fixedDimension) :
204	            image.get(fixedDimension, end)));
205	        int whiteRunSize = end - whiteRunStart;
206	        if (end >= maxDim || whiteRunSize > maxWhiteRun) {
207	          end = whiteRunStart;
208	          break;
209	        }
210	      }
211	    }
212	    end--;
213	
214	    return end > start ? new int[]{start, end} : null;
215	  }
216	
217	}

