165	  // Embed type information. On success, modify the matrix.
166	  static void embedTypeInfo(ErrorCorrectionLevel ecLevel, int maskPattern, ByteMatrix matrix)
167	      throws WriterException {
168	    BitArray typeInfoBits = new BitArray();
169	    makeTypeInfoBits(ecLevel, maskPattern, typeInfoBits);
170	
171	    for (int i = 0; i < typeInfoBits.getSize(); ++i) {
172	      // Place bits in LSB to MSB order.  LSB (least significant bit) is the last value in
173	      // "typeInfoBits".
174	      boolean bit = typeInfoBits.get(typeInfoBits.getSize() - 1 - i);
175	
176	      // Type info bits at the left top corner. See 8.9 of JISX0510:2004 (p.46).
177	      int[] coordinates = TYPE_INFO_COORDINATES[i];
178	      int x1 = coordinates[0];
179	      int y1 = coordinates[1];
180	      matrix.set(x1, y1, bit);
181	
182	      int x2;
183	      int y2;
184	      if (i < 8) {
185	        // Right top corner.
186	        x2 = matrix.getWidth() - i - 1;
187	        y2 = 8;
188	      } else {
189	        // Left bottom corner.
190	        x2 = 8;
191	        y2 = matrix.getHeight() - 7 + (i - 8);
192	      }
193	      matrix.set(x2, y2, bit);
194	    }
195	  }
196	
197	  // Embed version information if need be. On success, modify the matrix and return true.
198	  // See 8.10 of JISX0510:2004 (p.47) for how to embed version information.
199	  static void maybeEmbedVersionInfo(Version version, ByteMatrix matrix) throws WriterException {
200	    if (version.getVersionNumber() < 7) {  // Version info is necessary if version >= 7.
201	      return;  // Don't need version info.
202	    }
203	    BitArray versionInfoBits = new BitArray();
204	    makeVersionInfoBits(version, versionInfoBits);
205	
206	    int bitIndex = 6 * 3 - 1;  // It will decrease from 17 to 0.
207	    for (int i = 0; i < 6; ++i) {
208	      for (int j = 0; j < 3; ++j) {
209	        // Place bits in LSB (least significant bit) to MSB order.
210	        boolean bit = versionInfoBits.get(bitIndex);
211	        bitIndex--;
212	        // Left bottom corner.
213	        matrix.set(i, matrix.getHeight() - 11 + j, bit);
214	        // Right bottom corner.
215	        matrix.set(matrix.getHeight() - 11 + j, i, bit);
216	      }
217	    }
218	  }
219	
220	  // Embed "dataBits" using "getMaskPattern". On success, modify the matrix and return true.
221	  // For debugging purposes, it skips masking process if "getMaskPattern" is -1.
222	  // See 8.7 of JISX0510:2004 (p.38) for how to embed data bits.
223	  static void embedDataBits(BitArray dataBits, int maskPattern, ByteMatrix matrix)
224	      throws WriterException {
225	    int bitIndex = 0;
226	    int direction = -1;
227	    // Start from the right bottom cell.
228	    int x = matrix.getWidth() - 1;
229	    int y = matrix.getHeight() - 1;
230	    while (x > 0) {
231	      // Skip the vertical timing pattern.
232	      if (x == 6) {
233	        x -= 1;
234	      }
235	      while (y >= 0 && y < matrix.getHeight()) {
236	        for (int i = 0; i < 2; ++i) {
237	          int xx = x - i;
238	          // Skip the cell if it's not empty.
239	          if (!isEmpty(matrix.get(xx, y))) {
240	            continue;
241	          }
242	          boolean bit;
243	          if (bitIndex < dataBits.getSize()) {
244	            bit = dataBits.get(bitIndex);
245	            ++bitIndex;
246	          } else {
247	            // Padding bit. If there is no bit left, we'll fill the left cells with 0, as described
248	            // in 8.4.9 of JISX0510:2004 (p. 24).
249	            bit = false;
250	          }
251	
252	          // Skip masking if mask_pattern is -1.
253	          if (maskPattern != -1 && MaskUtil.getDataMaskBit(maskPattern, xx, y)) {
254	            bit = !bit;
255	          }
256	          matrix.set(xx, y, bit);
257	        }
258	        y += direction;
259	      }
260	      direction = -direction;  // Reverse the direction.
261	      y += direction;
262	      x -= 2;  // Move to the left.
263	    }
264	    // All bits should be consumed.
265	    if (bitIndex != dataBits.getSize()) {
266	      throw new WriterException("Not all bits consumed: " + bitIndex + '/' + dataBits.getSize());
267	    }
268	  }
269	
270	  // Return the position of the most significant bit set (to one) in the "value". The most
271	  // significant bit is position 32. If there is no bit set, return 0. Examples:
272	  // - findMSBSet(0) => 0
273	  // - findMSBSet(1) => 1
274	  // - findMSBSet(255) => 8
275	  static int findMSBSet(int value) {
276	    return 32 - Integer.numberOfLeadingZeros(value);
277	  }
278	
279	  // Calculate BCH (Bose-Chaudhuri-Hocquenghem) code for "value" using polynomial "poly". The BCH
280	  // code is used for encoding type information and version information.
281	  // Example: Calculation of version information of 7.
282	  // f(x) is created from 7.
283	  //   - 7 = 000111 in 6 bits
284	  //   - f(x) = x^2 + x^1 + x^0
285	  // g(x) is given by the standard (p. 67)
286	  //   - g(x) = x^12 + x^11 + x^10 + x^9 + x^8 + x^5 + x^2 + 1
287	  // Multiply f(x) by x^(18 - 6)
288	  //   - f'(x) = f(x) * x^(18 - 6)
289	  //   - f'(x) = x^14 + x^13 + x^12
290	  // Calculate the remainder of f'(x) / g(x)
291	  //         x^2
292	  //         __________________________________________________
293	  //   g(x) )x^14 + x^13 + x^12
294	  //         x^14 + x^13 + x^12 + x^11 + x^10 + x^7 + x^4 + x^2
295	  //         --------------------------------------------------
296	  //                              x^11 + x^10 + x^7 + x^4 + x^2
297	  //
298	  // The remainder is x^11 + x^10 + x^7 + x^4 + x^2
299	  // Encode it in binary: 110010010100
300	  // The return value is 0xc94 (1100 1001 0100)
301	  //
302	  // Since all coefficients in the polynomials are 1 or 0, we can do the calculation by bit
303	  // operations. We don't care if coefficients are positive or negative.
304	  static int calculateBCHCode(int value, int poly) {
305	    if (poly == 0) {
306	      throw new IllegalArgumentException("0 polynomial");
307	    }
308	    // If poly is "1 1111 0010 0101" (version info poly), msbSetInPoly is 13. We'll subtract 1
309	    // from 13 to make it 12.
310	    int msbSetInPoly = findMSBSet(poly);
311	    value <<= msbSetInPoly - 1;
312	    // Do the division business using exclusive-or operations.
313	    while (findMSBSet(value) >= msbSetInPoly) {
314	      value ^= poly << (findMSBSet(value) - msbSetInPoly);
315	    }
316	    // Now the "value" is the remainder (i.e. the BCH code)
317	    return value;
318	  }
319	
320	  // Make bit vector of type information. On success, store the result in "bits" and return true.
321	  // Encode error correction level and mask pattern. See 8.9 of
322	  // JISX0510:2004 (p.45) for details.
323	  static void makeTypeInfoBits(ErrorCorrectionLevel ecLevel, int maskPattern, BitArray bits)
324	      throws WriterException {
325	    if (!QRCode.isValidMaskPattern(maskPattern)) {
326	      throw new WriterException("Invalid mask pattern");
327	    }
328	    int typeInfo = (ecLevel.getBits() << 3) | maskPattern;
329	    bits.appendBits(typeInfo, 5);
330	
331	    int bchCode = calculateBCHCode(typeInfo, TYPE_INFO_POLY);
332	    bits.appendBits(bchCode, 10);
333	
334	    BitArray maskBits = new BitArray();
335	    maskBits.appendBits(TYPE_INFO_MASK_PATTERN, 15);
336	    bits.xor(maskBits);
337	
338	    if (bits.getSize() != 15) {  // Just in case.
339	      throw new WriterException("should not happen but we got: " + bits.getSize());
340	    }
341	  }
342	
343	  // Make bit vector of version information. On success, store the result in "bits" and return true.
344	  // See 8.10 of JISX0510:2004 (p.45) for details.
345	  static void makeVersionInfoBits(Version version, BitArray bits) throws WriterException {
346	    bits.appendBits(version.getVersionNumber(), 6);
347	    int bchCode = calculateBCHCode(version.getVersionNumber(), VERSION_INFO_POLY);
348	    bits.appendBits(bchCode, 12);
349	
350	    if (bits.getSize() != 18) {  // Just in case.
351	      throw new WriterException("should not happen but we got: " + bits.getSize());
352	    }
353	  }
354	
355	  // Check if "value" is empty.
356	  private static boolean isEmpty(int value) {
357	    return value == -1;
358	  }
359	
360	  private static void embedTimingPatterns(ByteMatrix matrix) {
361	    // -8 is for skipping position detection patterns (size 7), and two horizontal/vertical
362	    // separation patterns (size 1). Thus, 8 = 7 + 1.
363	    for (int i = 8; i < matrix.getWidth() - 8; ++i) {
364	      int bit = (i + 1) % 2;
365	      // Horizontal line.
366	      if (isEmpty(matrix.get(i, 6))) {
367	        matrix.set(i, 6, bit);
368	      }
369	      // Vertical line.
370	      if (isEmpty(matrix.get(6, i))) {
371	        matrix.set(6, i, bit);
372	      }
373	    }
374	  }
375	
376	  // Embed the lonely dark dot at left bottom corner. JISX0510:2004 (p.46)
377	  private static void embedDarkDotAtLeftBottomCorner(ByteMatrix matrix) throws WriterException {
378	    if (matrix.get(8, matrix.getHeight() - 8) == 0) {
379	      throw new WriterException();
380	    }
381	    matrix.set(8, matrix.getHeight() - 8, 1);
382	  }
383	
384	  private static void embedHorizontalSeparationPattern(int xStart,
385	                                                       int yStart,
386	                                                       ByteMatrix matrix) throws WriterException {
387	    for (int x = 0; x < 8; ++x) {
388	      if (!isEmpty(matrix.get(xStart + x, yStart))) {
389	        throw new WriterException();
390	      }
391	      matrix.set(xStart + x, yStart, 0);
392	    }
393	  }
394	
395	  private static void embedVerticalSeparationPattern(int xStart,
396	                                                     int yStart,
397	                                                     ByteMatrix matrix) throws WriterException {
398	    for (int y = 0; y < 7; ++y) {
399	      if (!isEmpty(matrix.get(xStart, yStart + y))) {
400	        throw new WriterException();
401	      }
402	      matrix.set(xStart, yStart + y, 0);
403	    }
404	  }
405	
406	  private static void embedPositionAdjustmentPattern(int xStart, int yStart, ByteMatrix matrix) {
407	    for (int y = 0; y < 5; ++y) {
408	      int[] patternY = POSITION_ADJUSTMENT_PATTERN[y];
409	      for (int x = 0; x < 5; ++x) {
410	        matrix.set(xStart + x, yStart + y, patternY[x]);
411	      }
412	    }
413	  }
414	
415	  private static void embedPositionDetectionPattern(int xStart, int yStart, ByteMatrix matrix) {
416	    for (int y = 0; y < 7; ++y) {
417	      int[] patternY = POSITION_DETECTION_PATTERN[y];
418	      for (int x = 0; x < 7; ++x) {
419	        matrix.set(xStart + x, yStart + y, patternY[x]);
420	      }
421	    }
422	  }
423	
424	  // Embed position detection patterns and surrounding vertical/horizontal separators.
425	  private static void embedPositionDetectionPatternsAndSeparators(ByteMatrix matrix) throws WriterException {
426	    // Embed three big squares at corners.
427	    int pdpWidth = POSITION_DETECTION_PATTERN[0].length;
428	    // Left top corner.
429	    embedPositionDetectionPattern(0, 0, matrix);
430	    // Right top corner.
431	    embedPositionDetectionPattern(matrix.getWidth() - pdpWidth, 0, matrix);
432	    // Left bottom corner.
433	    embedPositionDetectionPattern(0, matrix.getWidth() - pdpWidth, matrix);
434	
435	    // Embed horizontal separation patterns around the squares.
436	    int hspWidth = 8;
437	    // Left top corner.
438	    embedHorizontalSeparationPattern(0, hspWidth - 1, matrix);
439	    // Right top corner.
440	    embedHorizontalSeparationPattern(matrix.getWidth() - hspWidth,
441	        hspWidth - 1, matrix);
442	    // Left bottom corner.
443	    embedHorizontalSeparationPattern(0, matrix.getWidth() - hspWidth, matrix);
444	
445	    // Embed vertical separation patterns around the squares.
446	    int vspSize = 7;
447	    // Left top corner.
448	    embedVerticalSeparationPattern(vspSize, 0, matrix);
449	    // Right top corner.
450	    embedVerticalSeparationPattern(matrix.getHeight() - vspSize - 1, 0, matrix);
451	    // Left bottom corner.
452	    embedVerticalSeparationPattern(vspSize, matrix.getHeight() - vspSize,
453	        matrix);
454	  }
455	
456	  // Embed position adjustment patterns if need be.
457	  private static void maybeEmbedPositionAdjustmentPatterns(Version version, ByteMatrix matrix) {
458	    if (version.getVersionNumber() < 2) {  // The patterns appear if version >= 2
459	      return;
460	    }
461	    int index = version.getVersionNumber() - 1;
462	    int[] coordinates = POSITION_ADJUSTMENT_PATTERN_COORDINATE_TABLE[index];
463	    for (int y : coordinates) {
464	      if (y >= 0) {
465	        for (int x : coordinates) {
466	          if (x >= 0 && isEmpty(matrix.get(x, y))) {
467	            // If the cell is unset, we embed the position adjustment pattern here.
468	            // -2 is necessary since the x/y coordinates point to the center of the pattern, not the
469	            // left top corner.
470	            embedPositionAdjustmentPattern(x - 2, y - 2, matrix);
471	          }
472	        }
473	      }
474	    }
475	  }
