17	package com.google.zxing.pdf417.decoder.ec;
18	
19	import com.google.zxing.pdf417.PDF417Common;
20	
21	/**
22	 * <p>A field based on powers of a generator integer, modulo some modulus.</p>
23	 *
24	 * @author Sean Owen
25	 * @see com.google.zxing.common.reedsolomon.GenericGF
26	 */
27	public final class ModulusGF {
28	
29	  public static final ModulusGF PDF417_GF = new ModulusGF(PDF417Common.NUMBER_OF_CODEWORDS, 3);
30	
31	  private final int[] expTable;
32	  private final int[] logTable;
33	  private final ModulusPoly zero;
34	  private final ModulusPoly one;
35	  private final int modulus;
36	
37	  private ModulusGF(int modulus, int generator) {
38	    this.modulus = modulus;
39	    expTable = new int[modulus];
40	    logTable = new int[modulus];
41	    int x = 1;
42	    for (int i = 0; i < modulus; i++) {
43	      expTable[i] = x;
44	      x = (x * generator) % modulus;
45	    }
46	    for (int i = 0; i < modulus - 1; i++) {
47	      logTable[expTable[i]] = i;
48	    }
49	    // logTable[0] == 0 but this should never be used
50	    zero = new ModulusPoly(this, new int[]{0});
51	    one = new ModulusPoly(this, new int[]{1});
52	  }
53	
54	
55	  ModulusPoly getZero() {
56	    return zero;
57	  }
58	
59	  ModulusPoly getOne() {
60	    return one;
61	  }
62	
63	  ModulusPoly buildMonomial(int degree, int coefficient) {
64	    if (degree < 0) {
65	      throw new IllegalArgumentException();
66	    }
67	    if (coefficient == 0) {
68	      return zero;
69	    }
70	    int[] coefficients = new int[degree + 1];
71	    coefficients[0] = coefficient;
72	    return new ModulusPoly(this, coefficients);
73	  }
74	
75	  int add(int a, int b) {
76	    return (a + b) % modulus;
77	  }
78	
79	  int subtract(int a, int b) {
80	    return (modulus + a - b) % modulus;
81	  }
82	
83	  int exp(int a) {
84	    return expTable[a];
85	  }
86	
87	  int log(int a) {
88	    if (a == 0) {
89	      throw new IllegalArgumentException();
90	    }
91	    return logTable[a];
92	  }
93	
94	  int inverse(int a) {
95	    if (a == 0) {
96	      throw new ArithmeticException();
97	    }
98	    return expTable[modulus - logTable[a] - 1];
99	  }
100	
101	  int multiply(int a, int b) {
102	    if (a == 0 || b == 0) {
103	      return 0;
104	    }
105	    return expTable[(logTable[a] + logTable[b]) % (modulus - 1)];
106	  }
107	
108	  int getSize() {
109	    return modulus;
110	  }
111	
112	}
