17	package com.google.zxing.pdf417.decoder.ec;
18	
19	import com.google.zxing.ChecksumException;
20	
21	/**
22	 * <p>PDF417 error correction implementation.</p>
23	 *
24	 * <p>This <a href="http://en.wikipedia.org/wiki/Reed%E2%80%93Solomon_error_correction#Example">example</a>
25	 * is quite useful in understanding the algorithm.</p>
26	 *
27	 * @author Sean Owen
28	 * @see com.google.zxing.common.reedsolomon.ReedSolomonDecoder
29	 */
30	public final class ErrorCorrection {
31	
32	  private final ModulusGF field;
33	
34	  public ErrorCorrection() {
35	    this.field = ModulusGF.PDF417_GF;
36	  }
37	
38	  /**
39	   * @param received received codewords
40	   * @param numECCodewords number of those codewords used for EC
41	   * @param erasures location of erasures
42	   * @return number of errors
43	   * @throws ChecksumException if errors cannot be corrected, maybe because of too many errors
44	   */
45	  public int decode(int[] received,
46	                    int numECCodewords,
47	                    int[] erasures) throws ChecksumException {
48	
49	    if (received.length > field.getSize()) {
50	      // A codeword cannot be longer than the field; otherwise erasure and error positions
51	      // index past the exponent table in exp()/log().
52	      throw ChecksumException.getChecksumInstance();
53	    }
54	
55	    ModulusPoly poly = new ModulusPoly(field, received);
56	    int[] S = new int[numECCodewords];
57	    boolean error = false;
58	    for (int i = numECCodewords; i > 0; i--) {
59	      int eval = poly.evaluateAt(field.exp(i));
60	      S[numECCodewords - i] = eval;
61	      if (eval != 0) {
62	        error = true;
63	      }
64	    }
65	
66	    if (!error) {
67	      return 0;
68	    }
69	
70	    ModulusPoly knownErrors = field.getOne();
71	    if (erasures != null) {
72	      for (int erasure : erasures) {
73	        int b = field.exp(received.length - 1 - erasure);
74	        // Add (1 - bx) term:
75	        ModulusPoly term = new ModulusPoly(field, new int[]{field.subtract(0, b), 1});
76	        knownErrors = knownErrors.multiply(term);
77	      }
78	    }
79	
80	    ModulusPoly syndrome = new ModulusPoly(field, S);
81	    //syndrome = syndrome.multiply(knownErrors);
82	
83	    ModulusPoly[] sigmaOmega =
84	        runEuclideanAlgorithm(field.buildMonomial(numECCodewords, 1), syndrome, numECCodewords);
85	    ModulusPoly sigma = sigmaOmega[0];
86	    ModulusPoly omega = sigmaOmega[1];
87	
88	    //sigma = sigma.multiply(knownErrors);
89	
90	    int[] errorLocations = findErrorLocations(sigma);
91	    int[] errorMagnitudes = findErrorMagnitudes(omega, sigma, errorLocations);
92	
93	    for (int i = 0; i < errorLocations.length; i++) {
94	      int position = received.length - 1 - field.log(errorLocations[i]);
95	      if (position < 0) {
96	        throw ChecksumException.getChecksumInstance();
97	      }
98	      received[position] = field.subtract(received[position], errorMagnitudes[i]);
99	    }
100	    return errorLocations.length;
101	  }
102	
103	  private ModulusPoly[] runEuclideanAlgorithm(ModulusPoly a, ModulusPoly b, int R)
104	      throws ChecksumException {
105	    // Assume a's degree is >= b's
106	    if (a.getDegree() < b.getDegree()) {
107	      ModulusPoly temp = a;
108	      a = b;
109	      b = temp;
110	    }
111	
112	    ModulusPoly rLast = a;
113	    ModulusPoly r = b;
114	    ModulusPoly tLast = field.getZero();
115	    ModulusPoly t = field.getOne();
116	
117	    // Run Euclidean algorithm until r's degree is less than R/2
118	    while (r.getDegree() >= R / 2) {
119	      ModulusPoly rLastLast = rLast;
120	      ModulusPoly tLastLast = tLast;
121	      rLast = r;
122	      tLast = t;
123	
124	      // Divide rLastLast by rLast, with quotient in q and remainder in r
125	      if (rLast.isZero()) {
126	        // Oops, Euclidean algorithm already terminated?
127	        throw ChecksumException.getChecksumInstance();
128	      }
129	      r = rLastLast;
130	      ModulusPoly q = field.getZero();
131	      int denominatorLeadingTerm = rLast.getCoefficient(rLast.getDegree());
132	      int dltInverse = field.inverse(denominatorLeadingTerm);
133	      while (r.getDegree() >= rLast.getDegree() && !r.isZero()) {
134	        int degreeDiff = r.getDegree() - rLast.getDegree();
135	        int scale = field.multiply(r.getCoefficient(r.getDegree()), dltInverse);
136	        q = q.add(field.buildMonomial(degreeDiff, scale));
137	        r = r.subtract(rLast.multiplyByMonomial(degreeDiff, scale));
138	      }
139	
140	      t = q.multiply(tLast).subtract(tLastLast).negative();
141	    }
142	
143	    int sigmaTildeAtZero = t.getCoefficient(0);
144	    if (sigmaTildeAtZero == 0) {
145	      throw ChecksumException.getChecksumInstance();
146	    }
147	
148	    int inverse = field.inverse(sigmaTildeAtZero);
149	    ModulusPoly sigma = t.multiply(inverse);
150	    ModulusPoly omega = r.multiply(inverse);
151	    return new ModulusPoly[]{sigma, omega};
152	  }
153	
154	  private int[] findErrorLocations(ModulusPoly errorLocator) throws ChecksumException {
155	    // This is a direct application of Chien's search
156	    int numErrors = errorLocator.getDegree();
157	    int[] result = new int[numErrors];
158	    int e = 0;
159	    for (int i = 1; i < field.getSize() && e < numErrors; i++) {
160	      if (errorLocator.evaluateAt(i) == 0) {
161	        result[e] = field.inverse(i);
162	        e++;
163	      }
164	    }
165	    if (e != numErrors) {
166	      throw ChecksumException.getChecksumInstance();
167	    }
168	    return result;
169	  }
170	
171	  private int[] findErrorMagnitudes(ModulusPoly errorEvaluator,
172	                                    ModulusPoly errorLocator,
173	                                    int[] errorLocations) {
174	    int errorLocatorDegree = errorLocator.getDegree();
175	    if (errorLocatorDegree < 1) {
176	      return new int[0];
177	    }
178	    int[] formalDerivativeCoefficients = new int[errorLocatorDegree];
179	    for (int i = 1; i <= errorLocatorDegree; i++) {
180	      formalDerivativeCoefficients[errorLocatorDegree - i] =
181	          field.multiply(i, errorLocator.getCoefficient(i));
182	    }
183	    ModulusPoly formalDerivative = new ModulusPoly(field, formalDerivativeCoefficients);
184	
185	    // This is directly applying Forney's Formula
186	    int s = errorLocations.length;
187	    int[] result = new int[s];
188	    for (int i = 0; i < s; i++) {
189	      int xiInverse = field.inverse(errorLocations[i]);
190	      int numerator = field.subtract(0, errorEvaluator.evaluateAt(xiInverse));
191	      int denominator = field.inverse(formalDerivative.evaluateAt(xiInverse));
192	      result[i] = field.multiply(numerator, denominator);
193	    }
194	    return result;
195	  }
196	}
