432	  /**
433	   * Encode all of the message using Byte Compaction as described in ISO/IEC 15438:2001(E)
434	   *
435	   * @param input     the input
436	   * @param startpos  the start position within the message
437	   * @param count     the number of bytes to encode
438	   * @param startmode the mode from which this method starts
439	   * @param sb        receives the encoded codewords
440	   */
441	  private static void encodeMultiECIBinary(ECIInput input,
442	                                          int startpos,
443	                                          int count,
444	                                          int startmode,
445	                                          StringBuilder sb) throws WriterException {
446	    final int end = Math.min(startpos + count, input.length());
447	    int localStart = startpos;
448	    while (true) {
449	      //encode all leading ECIs and advance localStart
450	      while (localStart < end && input.isECI(localStart)) {
451	        encodingECI(input.getECIValue(localStart), sb);
452	        localStart++;
453	      }
454	      int localEnd = localStart;
455	      //advance end until before the next ECI
456	      while (localEnd < end && !input.isECI(localEnd)) {
457	        localEnd++;
458	      }
459	
460	      final int localCount = localEnd - localStart;
461	      if (localCount <= 0) {
462	        //done
463	        break;
464	      } else {
465	        //encode the segment
466	        encodeBinary(subBytes(input, localStart, localEnd),
467	            0, localCount, localStart == startpos ? startmode : BYTE_COMPACTION, sb);
468	        localStart = localEnd;
469	      }
470	    }
471	  }
472	
473	  static byte[] subBytes(ECIInput input, int start, int end) {
474	    final int count = end - start;
475	    byte[] result = new byte[count];
476	    for (int i = start; i < end; i++) {
477	      result[i - start] = (byte) (input.charAt(i) & 0xff);
478	    }
479	    return result;
480	  }
481	
482	  /**
483	   * Encode parts of the message using Byte Compaction as described in ISO/IEC 15438:2001(E),
484	   * chapter 4.4.3. The Unicode characters will be converted to binary using the cp437
485	   * codepage.
486	   *
487	   * @param bytes     the message converted to a byte array
488	   * @param startpos  the start position within the message
489	   * @param count     the number of bytes to encode
490	   * @param startmode the mode from which this method starts
491	   * @param sb        receives the encoded codewords
492	   */
493	  private static void encodeBinary(byte[] bytes,
494	                                   int startpos,
495	                                   int count,
496	                                   int startmode,
497	                                   StringBuilder sb) {
498	    if (count == 1 && startmode == TEXT_COMPACTION) {
499	      sb.append((char) SHIFT_TO_BYTE);
500	    } else {
501	      if ((count % 6) == 0) {
502	        sb.append((char) LATCH_TO_BYTE);
503	      } else {
504	        sb.append((char) LATCH_TO_BYTE_PADDED);
505	      }
506	    }
507	
508	    int idx = startpos;
509	    // Encode sixpacks
510	    if (count >= 6) {
511	      char[] chars = new char[5];
512	      while ((startpos + count - idx) >= 6) {
513	        long t = 0;
514	        for (int i = 0; i < 6; i++) {
515	          t <<= 8;
516	          t += bytes[idx + i] & 0xff;
517	        }
518	        for (int i = 0; i < 5; i++) {
519	          chars[i] = (char) (t % 900);
520	          t /= 900;
521	        }
522	        for (int i = chars.length - 1; i >= 0; i--) {
523	          sb.append(chars[i]);
524	        }
525	        idx += 6;
526	      }
527	    }
528	    //Encode rest (remaining n<5 bytes if any)
529	    for (int i = idx; i < startpos + count; i++) {
530	      int ch = bytes[i] & 0xff;
531	      sb.append((char) ch);
532	    }
533	  }
534	
535	  private static void encodeNumeric(ECIInput input, int startpos, int count, StringBuilder sb) {
536	    int idx = 0;
537	    StringBuilder tmp = new StringBuilder(count / 3 + 1);
538	    BigInteger num900 = BigInteger.valueOf(900);
539	    BigInteger num0 = BigInteger.valueOf(0);
540	    while (idx < count) {
541	      tmp.setLength(0);
542	      int len = Math.min(44, count - idx);
543	      String part = "1" + input.subSequence(startpos + idx, startpos + idx + len);
544	      BigInteger bigint = new BigInteger(part);
545	      do {
546	        tmp.append((char) bigint.mod(num900).intValue());
547	        bigint = bigint.divide(num900);
548	      } while (!bigint.equals(num0));
549	
550	      //Reverse temporary string
551	      for (int i = tmp.length() - 1; i >= 0; i--) {
552	        sb.append(tmp.charAt(i));
553	      }
554	      idx += len;
555	    }
556	  }
