559	  private static boolean isDigit(char ch) {
560	    return ch >= '0' && ch <= '9';
561	  }
562	
563	  private static boolean isAlphaUpper(char ch) {
564	    return ch == ' ' || (ch >= 'A' && ch <= 'Z');
565	  }
566	
567	  private static boolean isAlphaLower(char ch) {
568	    return ch == ' ' || (ch >= 'a' && ch <= 'z');
569	  }
570	
571	  private static boolean isMixed(char ch) {
572	    return MIXED[ch] != -1;
573	  }
574	
575	  private static boolean isPunctuation(char ch) {
576	    return PUNCTUATION[ch] != -1;
577	  }
578	
579	  private static boolean isText(char ch) {
580	    return ch == '\t' || ch == '\n' || ch == '\r' || (ch >= 32 && ch <= 126);
581	  }
