583	  /**
584	   * Determines the number of consecutive characters that are encodable using numeric compaction.
585	   *
586	   * @param input      the input
587	   * @param startpos the start position within the input
588	   * @return the requested character count
589	   */
590	  private static int determineConsecutiveDigitCount(ECIInput input, int startpos) {
591	    int count = 0;
592	    final int len = input.length();
593	    int idx = startpos;
594	    if (idx < len) {
595	      while (idx < len && !input.isECI(idx) && isDigit(input.charAt(idx))) {
596	        count++;
597	        idx++;
598	      }
599	    }
600	    return count;
601	  }
602	
603	  /**
604	   * Determines the number of consecutive characters that are encodable using text compaction.
605	   *
606	   * @param input      the input
607	   * @param startpos the start position within the input
608	   * @return the requested character count
609	   */
610	  private static int determineConsecutiveTextCount(ECIInput input, int startpos) {
611	    final int len = input.length();
612	    int idx = startpos;
613	    while (idx < len) {
614	      int numericCount = 0;
615	      while (numericCount < 13 && idx < len && !input.isECI(idx) && isDigit(input.charAt(idx))) {
616	        numericCount++;
617	        idx++;
618	      }
619	      if (numericCount >= 13) {
620	        return idx - startpos - numericCount;
621	      }
622	      if (numericCount > 0) {
623	        //Heuristic: All text-encodable chars or digits are binary encodable
624	        continue;
625	      }
626	
627	      //Check if character is encodable
628	      if (input.isECI(idx) || !isText(input.charAt(idx))) {
629	        break;
630	      }
631	      idx++;
632	    }
633	    return idx - startpos;
634	  }
635	
636	  /**
637	   * Determines the number of consecutive characters that are encodable using binary compaction.
638	   *
639	   * @param input    the input
640	   * @param startpos the start position within the message
641	   * @param encoding the charset used to convert the message to a byte array
642	   * @return the requested character count
643	   */
644	  private static int determineConsecutiveBinaryCount(ECIInput input, int startpos, Charset encoding)
645	      throws WriterException {
646	    CharsetEncoder encoder = encoding == null ? null : encoding.newEncoder();
647	    int len = input.length();
648	    int idx = startpos;
649	    while (idx < len) {
650	      int numericCount = 0;
651	
652	      int i = idx;
653	      while (numericCount < 13 && !input.isECI(i) && isDigit(input.charAt(i))) {
654	        numericCount++;
655	        //textCount++;
656	        i = idx + numericCount;
657	        if (i >= len) {
658	          break;
659	        }
660	      }
661	      if (numericCount >= 13) {
662	        return idx - startpos;
663	      }
664	
665	      if (encoder != null && !encoder.canEncode(input.charAt(idx))) {
666	        assert input instanceof NoECIInput;
667	        char ch = input.charAt(idx);
668	        throw new WriterException("Non-encodable character detected: " + ch + " (Unicode: " + (int) ch + ')');
669	      }
670	      idx++;
671	    }
672	    return idx - startpos;
673	  }
674	
675	  private static void encodingECI(int eci, StringBuilder sb) throws WriterException {
676	    if (eci >= 0 && eci < 900) {
677	      sb.append((char) ECI_CHARSET);
678	      sb.append((char) eci);
679	    } else if (eci < 810900) {
680	      sb.append((char) ECI_GENERAL_PURPOSE);
681	      sb.append((char) (eci / 900 - 1));
682	      sb.append((char) (eci % 900));
683	    } else if (eci < 811800) {
684	      sb.append((char) ECI_USER_DEFINED);
685	      sb.append((char) (810900 - eci));
686	    } else {
687	      throw new WriterException("ECI number not in valid range from 0..811799, but was " + eci);
688	    }
689	  }
