247	  /**
248	   * Choose the best mode by examining the content. Note that 'encoding' is used as a hint;
249	   * if it is Shift_JIS, and the input is only double-byte Kanji, then we return {@link Mode#KANJI}.
250	   */
251	  private static Mode chooseMode(String content, Charset encoding) {
252	    if (encoding != null &&
253	        ("Shift_JIS".equalsIgnoreCase(encoding.name()) || "SJIS".equalsIgnoreCase(encoding.name())) &&
254	        StringUtils.SHIFT_JIS_CHARSET != null &&
255	        StringUtils.SHIFT_JIS_CHARSET.equals(encoding) &&
256	        isOnlyDoubleByteKanji(content)) {
257	      // Choose Kanji mode if all input are double-byte characters
258	      return Mode.KANJI;
259	    }
260	    boolean hasNumeric = false;
261	    boolean hasAlphanumeric = false;
262	    for (int i = 0; i < content.length(); ++i) {
263	      char c = content.charAt(i);
264	      if (c >= '0' && c <= '9') {
265	        hasNumeric = true;
266	      } else if (getAlphanumericCode(c) != -1) {
267	        hasAlphanumeric = true;
268	      } else {
269	        return Mode.BYTE;
270	      }
271	    }
272	    if (hasAlphanumeric) {
273	      return Mode.ALPHANUMERIC;
274	    }
275	    if (hasNumeric) {
276	      return Mode.NUMERIC;
277	    }
278	    return Mode.BYTE;
279	  }
280	
281	  static boolean isOnlyDoubleByteKanji(String content) {
282	    byte[] bytes = content.getBytes(StringUtils.SHIFT_JIS_CHARSET);
283	    int length = bytes.length;
284	    if (length % 2 != 0) {
285	      return false;
286	    }
287	    for (int i = 0; i < length; i += 2) {
288	      int byte1 = bytes[i] & 0xFF;
289	      if ((byte1 < 0x81 || byte1 > 0x9F) && (byte1 < 0xE0 || byte1 > 0xEB)) {
290	        return false;
291	      }
292	    }
293	    return true;
294	  }
