296	  private static int chooseMaskPattern(BitArray bits,
297	                                       ErrorCorrectionLevel ecLevel,
298	                                       Version version,
299	                                       ByteMatrix matrix) throws WriterException {
300	
301	    int minPenalty = Integer.MAX_VALUE;  // Lower penalty is better.
302	    int bestMaskPattern = -1;
303	    // We try all mask patterns to choose the best one.
304	    for (int maskPattern = 0; maskPattern < QRCode.NUM_MASK_PATTERNS; maskPattern++) {
305	      MatrixUtil.buildMatrix(bits, ecLevel, version, maskPattern, matrix);
306	      int penalty = calculateMaskPenalty(matrix);
307	      if (penalty < minPenalty) {
308	        minPenalty = penalty;
309	        bestMaskPattern = maskPattern;
310	      }
311	    }
312	    return bestMaskPattern;
313	  }
314	
315	  private static Version chooseVersion(int numInputBits, ErrorCorrectionLevel ecLevel) throws WriterException {
316	    for (int versionNum = 1; versionNum <= 40; versionNum++) {
317	      Version version = Version.getVersionForNumber(versionNum);
318	      if (willFit(numInputBits, version, ecLevel)) {
319	        return version;
320	      }
321	    }
322	    throw new WriterException("Data too big");
323	  }
324	
325	  /**
326	   * @return true if the number of input bits will fit in a code with the specified version and
327	   * error correction level.
328	   */
329	  static boolean willFit(int numInputBits, Version version, ErrorCorrectionLevel ecLevel) {
330	    // In the following comments, we use numbers of Version 7-H.
331	    // numBytes = 196
332	    int numBytes = version.getTotalCodewords();
333	    // getNumECBytes = 130
334	    Version.ECBlocks ecBlocks = version.getECBlocksForLevel(ecLevel);
335	    int numEcBytes = ecBlocks.getTotalECCodewords();
336	    // getNumDataBytes = 196 - 130 = 66
337	    int numDataBytes = numBytes - numEcBytes;
338	    int totalInputBytes = (numInputBits + 7) / 8;
339	    return numDataBytes >= totalInputBytes;
340	  }
341	
342	  /**
343	   * Terminate bits as described in 8.4.8 and 8.4.9 of JISX0510:2004 (p.24).
344	   */
345	  static void terminateBits(int numDataBytes, BitArray bits) throws WriterException {
346	    int capacity = numDataBytes * 8;
347	    if (bits.getSize() > capacity) {
348	      throw new WriterException("data bits cannot fit in the QR Code" + bits.getSize() + " > " +
349	          capacity);
350	    }
351	    // Append Mode.TERMINATE if there is enough space (value is 0000)
352	    for (int i = 0; i < 4 && bits.getSize() < capacity; ++i) {
353	      bits.appendBit(false);
354	    }
355	    // Append termination bits. See 8.4.8 of JISX0510:2004 (p.24) for details.
356	    // If the last byte isn't 8-bit aligned, we'll add padding bits.
357	    int numBitsInLastByte = bits.getSize() & 0x07;
358	    if (numBitsInLastByte > 0) {
359	      for (int i = numBitsInLastByte; i < 8; i++) {
360	        bits.appendBit(false);
361	      }
362	    }
363	    // If we have more space, we'll fill the space with padding patterns defined in 8.4.9 (p.24).
364	    int numPaddingBytes = numDataBytes - bits.getSizeInBytes();
365	    for (int i = 0; i < numPaddingBytes; ++i) {
366	      bits.appendBits((i & 0x01) == 0 ? 0xEC : 0x11, 8);
367	    }
368	    if (bits.getSize() != capacity) {
369	      throw new WriterException("Bits size does not equal capacity");
370	    }
371	  }
372	
373	  /**
374	   * Get number of data bytes and number of error correction bytes for block id "blockID". Store
375	   * the result in "numDataBytesInBlock", and "numECBytesInBlock". See table 12 in 8.5.1 of
376	   * JISX0510:2004 (p.30)
377	   */
378	  static void getNumDataBytesAndNumECBytesForBlockID(int numTotalBytes,
379	                                                     int numDataBytes,
380	                                                     int numRSBlocks,
381	                                                     int blockID,
382	                                                     int[] numDataBytesInBlock,
383	                                                     int[] numECBytesInBlock) throws WriterException {
384	    if (blockID >= numRSBlocks) {
385	      throw new WriterException("Block ID too large");
386	    }
387	    // numRsBlocksInGroup2 = 196 % 5 = 1
388	    int numRsBlocksInGroup2 = numTotalBytes % numRSBlocks;
389	    // numRsBlocksInGroup1 = 5 - 1 = 4
390	    int numRsBlocksInGroup1 = numRSBlocks - numRsBlocksInGroup2;
391	    // numTotalBytesInGroup1 = 196 / 5 = 39
392	    int numTotalBytesInGroup1 = numTotalBytes / numRSBlocks;
393	    // numTotalBytesInGroup2 = 39 + 1 = 40
394	    int numTotalBytesInGroup2 = numTotalBytesInGroup1 + 1;
395	    // numDataBytesInGroup1 = 66 / 5 = 13
396	    int numDataBytesInGroup1 = numDataBytes / numRSBlocks;
397	    // numDataBytesInGroup2 = 13 + 1 = 14
398	    int numDataBytesInGroup2 = numDataBytesInGroup1 + 1;
399	    // numEcBytesInGroup1 = 39 - 13 = 26
400	    int numEcBytesInGroup1 = numTotalBytesInGroup1 - numDataBytesInGroup1;
401	    // numEcBytesInGroup2 = 40 - 14 = 26
402	    int numEcBytesInGroup2 = numTotalBytesInGroup2 - numDataBytesInGroup2;
403	    // Sanity checks.
404	    // 26 = 26
405	    if (numEcBytesInGroup1 != numEcBytesInGroup2) {
406	      throw new WriterException("EC bytes mismatch");
407	    }
408	    // 5 = 4 + 1.
409	    if (numRSBlocks != numRsBlocksInGroup1 + numRsBlocksInGroup2) {
410	      throw new WriterException("RS blocks mismatch");
411	    }
412	    // 196 = (13 + 26) * 4 + (14 + 26) * 1
413	    if (numTotalBytes !=
414	        ((numDataBytesInGroup1 + numEcBytesInGroup1) *
415	            numRsBlocksInGroup1) +
416	            ((numDataBytesInGroup2 + numEcBytesInGroup2) *
417	                numRsBlocksInGroup2)) {
418	      throw new WriterException("Total bytes mismatch");
419	    }
420	
421	    if (blockID < numRsBlocksInGroup1) {
422	      numDataBytesInBlock[0] = numDataBytesInGroup1;
423	      numECBytesInBlock[0] = numEcBytesInGroup1;
424	    } else {
425	      numDataBytesInBlock[0] = numDataBytesInGroup2;
426	      numECBytesInBlock[0] = numEcBytesInGroup2;
427	    }
428	  }
429	
430	  /**
431	   * Interleave "bits" with corresponding error correction bytes. On success, store the result in
432	   * "result". The interleave rule is complicated. See 8.6 of JISX0510:2004 (p.37) for details.
433	   */
434	  static BitArray interleaveWithECBytes(BitArray bits,
435	                                        int numTotalBytes,
436	                                        int numDataBytes,
437	                                        int numRSBlocks) throws WriterException {
438	
439	    // "bits" must have "getNumDataBytes" bytes of data.
440	    if (bits.getSizeInBytes() != numDataBytes) {
441	      throw new WriterException("Number of bits and data bytes does not match");
442	    }
443	
444	    // Step 1.  Divide data bytes into blocks and generate error correction bytes for them. We'll
445	    // store the divided data bytes blocks and error correction bytes blocks into "blocks".
446	    int dataBytesOffset = 0;
447	    int maxNumDataBytes = 0;
448	    int maxNumEcBytes = 0;
449	
450	    // Since, we know the number of reedsolmon blocks, we can initialize the vector with the number.
451	    Collection<BlockPair> blocks = new ArrayList<>(numRSBlocks);
452	
453	    for (int i = 0; i < numRSBlocks; ++i) {
454	      int[] numDataBytesInBlock = new int[1];
455	      int[] numEcBytesInBlock = new int[1];
456	      getNumDataBytesAndNumECBytesForBlockID(
457	          numTotalBytes, numDataBytes, numRSBlocks, i,
458	          numDataBytesInBlock, numEcBytesInBlock);
459	
460	      int size = numDataBytesInBlock[0];
461	      byte[] dataBytes = new byte[size];
462	      bits.toBytes(8 * dataBytesOffset, dataBytes, 0, size);
463	      byte[] ecBytes = generateECBytes(dataBytes, numEcBytesInBlock[0]);
464	      blocks.add(new BlockPair(dataBytes, ecBytes));
465	
466	      maxNumDataBytes = Math.max(maxNumDataBytes, size);
467	      maxNumEcBytes = Math.max(maxNumEcBytes, ecBytes.length);
468	      dataBytesOffset += numDataBytesInBlock[0];
469	    }
470	    if (numDataBytes != dataBytesOffset) {
471	      throw new WriterException("Data bytes does not match offset");
472	    }
473	
474	    BitArray result = new BitArray();
475	
476	    // First, place data blocks.
477	    for (int i = 0; i < maxNumDataBytes; ++i) {
478	      for (BlockPair block : blocks) {
479	        byte[] dataBytes = block.getDataBytes();
480	        if (i < dataBytes.length) {
481	          result.appendBits(dataBytes[i], 8);
482	        }
483	      }
484	    }
485	    // Then, place error correction blocks.
486	    for (int i = 0; i < maxNumEcBytes; ++i) {
487	      for (BlockPair block : blocks) {
488	        byte[] ecBytes = block.getErrorCorrectionBytes();
489	        if (i < ecBytes.length) {
490	          result.appendBits(ecBytes[i], 8);
491	        }
492	      }
493	    }
494	    if (numTotalBytes != result.getSizeInBytes()) {  // Should be same.
495	      throw new WriterException("Interleaving error: " + numTotalBytes + " and " +
496	          result.getSizeInBytes() + " differ.");
497	    }
498	
499	    return result;
500	  }
501	
502	  static byte[] generateECBytes(byte[] dataBytes, int numEcBytesInBlock) {
503	    int numDataBytes = dataBytes.length;
504	    int[] toEncode = new int[numDataBytes + numEcBytesInBlock];
505	    for (int i = 0; i < numDataBytes; i++) {
506	      toEncode[i] = dataBytes[i] & 0xFF;
507	    }
508	    new ReedSolomonEncoder(GenericGF.QR_CODE_FIELD_256).encode(toEncode, numEcBytesInBlock);
509	
510	    byte[] ecBytes = new byte[numEcBytesInBlock];
511	    for (int i = 0; i < numEcBytesInBlock; i++) {
512	      ecBytes[i] = (byte) toEncode[numDataBytes + i];
513	    }
514	    return ecBytes;
515	  }
