525	  /**
526	   * Append length info. On success, store the result in "bits".
527	   */
528	  static void appendLengthInfo(int numLetters, Version version, Mode mode, BitArray bits) throws WriterException {
529	    int numBits = mode.getCharacterCountBits(version);
530	    if (numLetters >= (1 << numBits)) {
531	      throw new WriterException(numLetters + " is bigger than " + ((1 << numBits) - 1));
532	    }
533	    bits.appendBits(numLetters, numBits);
534	  }
