536	  /**
537	   * Append "bytes" in "mode" mode (encoding) into "bits". On success, store the result in "bits".
538	   */
539	  static void appendBytes(String content,
540	                          Mode mode,
541	                          BitArray bits,
542	                          Charset encoding) throws WriterException {
543	    switch (mode) {
544	      case NUMERIC:
545	        appendNumericBytes(content, bits);
546	        break;
547	      case ALPHANUMERIC:
548	        appendAlphanumericBytes(content, bits);
549	        break;
550	      case BYTE:
551	        append8BitBytes(content, bits, encoding);
552	        break;
553	      case KANJI:
554	        appendKanjiBytes(content, bits);
555	        break;
556	      default:
557	        throw new WriterException("Invalid mode: " + mode);
558	    }
559	  }
560	
561	  static void appendNumericBytes(CharSequence content, BitArray bits) {
562	    int length = content.length();
563	    int i = 0;
564	    while (i < length) {
565	      int num1 = content.charAt(i) - '0';
566	      if (i + 2 < length) {
567	        // Encode three numeric letters in ten bits.
568	        int num2 = content.charAt(i + 1) - '0';
569	        int num3 = content.charAt(i + 2) - '0';
570	        bits.appendBits(num1 * 100 + num2 * 10 + num3, 10);
571	        i += 3;
572	      } else if (i + 1 < length) {
573	        // Encode two numeric letters in seven bits.
574	        int num2 = content.charAt(i + 1) - '0';
575	        bits.appendBits(num1 * 10 + num2, 7);
576	        i += 2;
577	      } else {
578	        // Encode one numeric letter in four bits.
579	        bits.appendBits(num1, 4);
580	        i++;
581	      }
582	    }
583	  }
584	
585	  static void appendAlphanumericBytes(CharSequence content, BitArray bits) throws WriterException {
586	    int length = content.length();
587	    int i = 0;
588	    while (i < length) {
589	      int code1 = getAlphanumericCode(content.charAt(i));
590	      if (code1 == -1) {
591	        throw new WriterException();
592	      }
593	      if (i + 1 < length) {
594	        int code2 = getAlphanumericCode(content.charAt(i + 1));
595	        if (code2 == -1) {
596	          throw new WriterException();
597	        }
598	        // Encode two alphanumeric letters in 11 bits.
599	        bits.appendBits(code1 * 45 + code2, 11);
600	        i += 2;
601	      } else {
602	        // Encode one alphanumeric letter in six bits.
603	        bits.appendBits(code1, 6);
604	        i++;
605	      }
606	    }
607	  }
608	
609	  static void append8BitBytes(String content, BitArray bits, Charset encoding) {
610	    byte[] bytes = content.getBytes(encoding);
611	    for (byte b : bytes) {
612	      bits.appendBits(b, 8);
613	    }
614	  }
615	
616	  static void appendKanjiBytes(String content, BitArray bits) throws WriterException {
617	    if (StringUtils.SHIFT_JIS_CHARSET == null) {
618	      // Not supported without charset support
619	      throw new WriterException("SJIS Charset not supported on this platform");
620	    }
621	    byte[] bytes = content.getBytes(StringUtils.SHIFT_JIS_CHARSET);
622	    if (bytes.length % 2 != 0) {
623	      throw new WriterException("Kanji byte size not even");
624	    }
625	    int maxI = bytes.length - 1; // bytes.length must be even
626	    for (int i = 0; i < maxI; i += 2) {
627	      int byte1 = bytes[i] & 0xFF;
628	      int byte2 = bytes[i + 1] & 0xFF;
629	      int code = (byte1 << 8) | byte2;
630	      int subtracted = -1;
631	      if (code >= 0x8140 && code <= 0x9ffc) {
632	        subtracted = code - 0x8140;
633	      } else if (code >= 0xe040 && code <= 0xebbf) {
634	        subtracted = code - 0xc140;
635	      }
636	      if (subtracted == -1) {
637	        throw new WriterException("Invalid byte sequence");
638	      }
639	      int encoded = ((subtracted >> 8) * 0xc0) + (subtracted & 0xff);
640	      bits.appendBits(encoded, 13);
641	    }
642	  }
643	
644	  private static void appendECI(CharacterSetECI eci, BitArray bits) {
645	    bits.appendBits(Mode.ECI.getBits(), 4);
646	    // This is correct for values up to 127, which is all we need now.
647	    bits.appendBits(eci.getValue(), 8);
648	  }
