private static void embedTimingPatterns(ByteMatrix matrix) {
  // -8 is for skipping position detection patterns (size 7), and two horizontal/vertical
  // separation patterns (size 1). Thus, 8 = 7 + 1.
  for (int i = 8; i < matrix.getWidth() - 8; ++i) {
    int bit = (i + 1) % 2;
    // Horizontal line.
    if (isEmpty(matrix.get(i, 6))) {
      matrix.set(i, 6, bit);
    }
    // Vertical line.
    if (isEmpty(matrix.get(6, i))) {
      matrix.set(6, i, bit);
    }
  }
}

// Embed the lonely dark dot at left bottom corner. JISX0510:2004 (p.46)
private static void embedDarkDotAtLeftBottomCorner(ByteMatrix matrix) throws WriterException {
  if (matrix.get(8, matrix.getHeight() - 8) == 0) {
    throw new WriterException();
  }
  matrix.set(8, matrix.getHeight() - 8, 1);
}

private static void embedHorizontalSeparationPattern(int xStart,
                                                     int yStart,
                                                     ByteMatrix matrix) throws WriterException {
  for (int x = 0; x < 8; ++x) {
    if (!isEmpty(matrix.get(xStart + x, yStart))) {
      throw new WriterException();
    }
    matrix.set(xStart + x, yStart, 0);
  }
}

private static void embedVerticalSeparationPattern(int xStart,
                                                   int yStart,
                                                   ByteMatrix matrix) throws WriterException {
  for (int y = 0; y < 7; ++y) {
    if (!isEmpty(matrix.get(xStart, yStart + y))) {
      throw new WriterException();
    }
    matrix.set(xStart, yStart + y, 0);
  }
}

private static void embedPositionAdjustmentPattern(int xStart, int yStart, ByteMatrix matrix) {
  for (int y = 0; y < 5; ++y) {
    int[] patternY = POSITION_ADJUSTMENT_PATTERN[y];
    for (int x = 0; x < 5; ++x) {
      matrix.set(xStart + x, yStart + y, patternY[x]);
    }
  }
}

private static void embedPositionDetectionPattern(int xStart, int yStart, ByteMatrix matrix) {
  for (int y = 0; y < 7; ++y) {
    int[] patternY = POSITION_DETECTION_PATTERN[y];
    for (int x = 0; x < 7; ++x) {
      matrix.set(xStart + x, yStart + y, patternY[x]);
    }
  }
}

// Embed position detection patterns and surrounding vertical/horizontal separators.
private static void embedPositionDetectionPatternsAndSeparators(ByteMatrix matrix) throws WriterException {
  // Embed three big squares at corners.
  int pdpWidth = POSITION_DETECTION_PATTERN[0].length;
  // Left top corner.
  embedPositionDetectionPattern(0, 0, matrix);
  // Right top corner.
  embedPositionDetectionPattern(matrix.getWidth() - pdpWidth, 0, matrix);
  // Left bottom corner.
  embedPositionDetectionPattern(0, matrix.getWidth() - pdpWidth, matrix);

