import java.io.File;
import java.lang.reflect.Method;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.Random;

/** Differential test: QR Encoder.encode (which builds the matrix via MatrixUtil) old vs new. */
public final class QrDiff {

  static URLClassLoader loader(String dir) throws Exception {
    return new URLClassLoader(new URL[]{ new File(dir).toURI().toURL() }, null);
  }

  static final class Api {
    final Method encode;        // Encoder.encode(String, ErrorCorrectionLevel)
    final Object[] ecLevels;    // L, M, Q, H
    final Method getMatrix;     // QRCode.getMatrix()
    final Method getVersion;    // QRCode.getVersion()
    Api(ClassLoader cl) throws Exception {
      Class<?> ecl = Class.forName("com.google.zxing.qrcode.decoder.ErrorCorrectionLevel", true, cl);
